import React, { useId } from 'react';
import { chakra, Drawer, DrawerOverlay, useMultiStyleConfig, useModalContext, ModalFocusScope } from '@chakra-ui/react';
import type { SystemStyleObject } from '@chakra-ui/react';
import { motion } from 'framer-motion';
import { ZimmButton } from 'app/components/ui-kits/atoms/zimmButton';
import { useUiCopy } from 'app/hooks/useUiCopy';

const ZIMM_DRAWER_RECIPE = 'ZimmDrawer';

// framer-motion's `Transition.ease` wants a literal, mutable 4-tuple (`BezierDefinition`) — a
// plain array literal infers as `number[]`, and `as const` infers a *readonly* tuple, neither of
// which satisfies it, hence the explicit cast.
const BEZIER_SLIDES_EASING = [0.87, 0, 0.13, 1] as [number, number, number, number];
// Mirrors theme/foundation/motion.ts's `duration.default` (300ms) and `easing.slides`
// (cubic-bezier(0.87, 0, 0.13, 1), "panels and overlays entering the screen") — hand-converted
// to framer-motion's shape (seconds, not ms; a bezier tuple, not a CSS `cubic-bezier()` string)
// since motion.ts's tokens are CSS-string form and framer-motion doesn't accept that form. One
// shared value for both enter and exit — that symmetry is the whole point (SFCC-898).
const DRAWER_TRANSITION = { duration: 0.3, ease: BEZIER_SLIDES_EASING };

// `motion(chakra.div)` — framer OUTSIDE, chakra INSIDE. This ordering matters: framer's
// `motion()` only intercepts its own known animation props (initial/animate/exit/transition/
// variants) and forwards everything else straight to the wrapped component, so `transition`
// reaches framer-motion directly here. Chakra's OWN internal Drawer does the reverse
// (`chakra(Slide)`) — chakra wraps the animated component — and chakra's `shouldForwardProp`
// treats any prop literally named `transition` as a CSS shorthand style prop (it's a real
// Chakra/styled-system prop name), silently swallowing it before it ever reaches the wrapped
// component's real props (confirmed directly in @chakra-ui/system's should-forward-prop.js).
// That's why `<DrawerContent transition={...}>` had no effect and why this file no longer uses
// Chakra's `<DrawerContent>` at all — SFCC-898's close-animation defect (asymmetric enter/exit;
// Chakra's own Slide defaults to a spring-physics enter vs. a fixed 150ms tween exit, per
// @chakra-ui/transition's slide.js) can't be fixed through any prop that component exposes.
const MotionChakraDiv = motion(chakra.div);

// Matches Figma's own named drawer sizes exactly (SFCC-898) — see zimmDrawer.css.ts's
// file-level comment for the width/usage table. `xLarge` has no consumer yet (Cart is a full
// page today, not a drawer).
export type ZimmDrawerSize = 'large' | 'tablet' | 'small' | 'xLarge' | 'mobile' | 'prompt';

type ZimmDrawerBaseProps = {
  /** Whether the drawer is open. */
  isOpen: boolean;
  /** Called on backdrop click, Escape, and the close button (all via Chakra's Drawer). */
  onClose: () => void;
  /** Desktop/tablet width variant — see ZimmDrawerSize. Collapses to the mobile treatment
   *  below the tablet breakpoint regardless of which value is chosen — see zimmDrawer.css.ts. */
  size: ZimmDrawerSize;
  children: React.ReactNode;
  /** Text style for the title. 'large' applies heading1 (24px, uppercase, Futura Round regular);
   *  'small' applies body2Strong (14px bold). Defaults to 'large'. Only relevant when `title`
   *  is provided. */
  titleStyle?: 'large' | 'small';
  /** Element to focus when the drawer closes. Use when the trigger may not have received
   *  keyboard focus before opening (e.g. mouse click) — without this Chakra falls back to
   *  document.body and AC10 focus-return fails. */
  finalFocusRef?: React.RefObject<HTMLElement>;
  /** Element to focus when the drawer opens. Overrides Chakra's default (first focusable element
   *  in the panel, usually the close button) — use to land focus directly on the primary input. */
  initialFocusRef?: React.RefObject<HTMLElement>;
};

/**
 * Exactly one of:
 * - `title`       — renders an inline header row (title left, close button right); the drawer's
 *                   accessible name is derived from the rendered title element automatically.
 * - `labelledBy`  — ID of an existing element that labels the drawer (e.g. ZimmPdpDrawer's own
 *                   tab header). Paired with the floating close button.
 * - `aria-label`  — explicit string label when neither a visible title nor a separate element
 *                   is available.
 */
type ZimmDrawerProps = ZimmDrawerBaseProps &
  (
    | { title: string; labelledBy?: never; 'aria-label'?: never }
    | { title?: never; labelledBy: string; 'aria-label'?: never }
    | { title?: never; labelledBy?: never; 'aria-label': string }
  );

// Deliberately not named `ZimmDrawerContentProps` — scripts/generateRegistry.mjs's
// extractTsProps merges every `*Props`-suffixed type in a file into one component's registry
// row when it can't isolate the preferred one (ZimmDrawerProps' multi-line union body isn't
// matched by its regex, which can't cross a newline — a documented limitation, not a bug to
// patch there). That merge was leaking this internal helper's own fields (ariaLabel,
// contentStyles, closeButtonStyles) into ZimmDrawer's public registry entry.
type ZimmDrawerContentConfig = {
  children: React.ReactNode;
  onClose: () => void;
  /** Renders an inline header row (title left, close button right) instead of the floating
   *  close button when provided — see ZimmDrawerProps' `title` member. */
  title?: string;
  titleId?: string;
  titleStyle?: 'large' | 'small';
  labelledBy?: string;
  ariaLabel?: string;
  contentStyles: SystemStyleObject;
  headerStyles: SystemStyleObject;
  headerTitleStyles: SystemStyleObject;
  closeButtonStyles: SystemStyleObject;
};

/**
 * Replaces Chakra's own `<DrawerContent>` — see the `MotionChakraDiv` comment above for why.
 * Reuses Chakra's real dialog/focus/aria mechanics directly (`useModalContext`,
 * `ModalFocusScope` — both genuinely public exports, not reaching into Chakra internals) so
 * focus trap, initial focus, focus restore, body-scroll lock, and Escape/overlay-click-to-close
 * all still come from Chakra exactly as before; only the slide transition itself is now ours.
 *
 * Renders either an inline title row (title left, close button right) when `title` is passed, or
 * a floating close button only — see ZimmDrawer's own docblock for when each is used.
 *
 * @param props see ZimmDrawerContentConfig
 */
const ZimmDrawerContent = ({
  children,
  onClose,
  title,
  titleId,
  titleStyle = 'large',
  labelledBy,
  ariaLabel,
  contentStyles,
  headerStyles,
  headerTitleStyles,
  closeButtonStyles,
}: ZimmDrawerContentConfig) => {
  const { t } = useUiCopy();
  const { getDialogProps, getDialogContainerProps } = useModalContext();
  const dialogProps = getDialogProps({ 'aria-label': ariaLabel });
  // getDialogProps always computes `aria-labelledby` from Chakra's own <DrawerHeader> mount
  // state, which ZimmDrawer never renders (no header sub-component in this tree) — so it
  // always resolves to undefined regardless of what's passed in above. Set it directly so the
  // `title` and `labelledBy` prop variants of ZimmDrawerProps actually work.
  if (title && titleId) {
    dialogProps['aria-labelledby'] = titleId;
  } else if (labelledBy) {
    dialogProps['aria-labelledby'] = labelledBy;
  }
  const containerProps = getDialogContainerProps();

  return (
    <ModalFocusScope>
      <chakra.div {...containerProps} __css={{ position: 'fixed', inset: 0, display: 'flex', zIndex: 'modal' }}>
        <MotionChakraDiv
          {...dialogProps}
          initial={{ x: '100%' }}
          animate={{ x: 0 }}
          exit={{ x: '100%' }}
          transition={DRAWER_TRANSITION}
          __css={{ position: 'fixed', top: 0, right: 0, bottom: 0, outline: 0, ...contentStyles }}
        >
          {title ? (
            <chakra.div sx={headerStyles}>
              <chakra.span
                id={titleId}
                sx={headerTitleStyles}
                textStyle={titleStyle === 'small' ? 'body2Strong' : 'heading1'}
              >
                {title}
              </chakra.span>
              <ZimmButton variant="icon" icon="close" label={t('drawer.close', 'Close')} onClick={onClose} />
            </chakra.div>
          ) : (
            <chakra.div sx={closeButtonStyles}>
              <ZimmButton variant="icon" icon="close" label={t('drawer.close', 'Close')} onClick={onClose} />
            </chakra.div>
          )}
          {children}
        </MotionChakraDiv>
      </chakra.div>
    </ModalFocusScope>
  );
};

/**
 * Generic right-anchored slide-in drawer shell — overlay, panel, and a Figma-matched size
 * variant (see ZimmDrawerSize), built on Chakra's Drawer primitive (focus trap, initial focus,
 * focus restore, body-scroll lock, and Escape/overlay-click-to-close all come from Chakra, not
 * hand-rolled).
 *
 * Pass `title` to render an inline header row (title text left, close button right) sized per the
 * Figma drawer/header frames. Omit `title` and pass `labelledBy`/`aria-label` instead for drawers
 * that supply their own header (e.g. ZimmPdpDrawer's tab row), which keeps the floating close
 * button behaviour.
 *
 * @param props see ZimmDrawerProps
 */
export const ZimmDrawer = (props: ZimmDrawerProps) => {
  const { isOpen, onClose, size, children, titleStyle = 'large', finalFocusRef, initialFocusRef } = props;
  const styles = useMultiStyleConfig(ZIMM_DRAWER_RECIPE, { variant: size });
  const titleId = useId();

  const title = 'title' in props ? props.title : undefined;
  const labelledBy = !title && 'labelledBy' in props ? props.labelledBy : undefined;
  const ariaLabel = !title && 'aria-label' in props ? props['aria-label'] : undefined;

  // Chakra's FocusLock remains active during the exit animation, so any focus call made
  // while the drawer is still mounted (rAF, close-button onClick) gets trapped and dropped.
  // onCloseComplete fires after the animation finishes and FocusLock is released — the only
  // reliable moment to restore focus. Covers both close-button click and Escape for all
  // consumers that pass finalFocusRef.
  const handleCloseComplete = () => {
    if (finalFocusRef) finalFocusRef.current?.focus();
  };

  return (
    <Drawer
      isOpen={isOpen}
      onClose={onClose}
      placement="right"
      onCloseComplete={handleCloseComplete}
      initialFocusRef={initialFocusRef}
    >
      <DrawerOverlay sx={styles.overlay} />
      {/* aria-labelledby (not aria-label) for the title case: Chakra's own <DrawerContent>
          would clobber it with its own headingId (undefined without a DrawerHeader), but
          ZimmDrawerContent bypasses <DrawerContent> entirely and sets dialogProps itself
          (see its own comment above) — the clobbering bug this would otherwise work around
          doesn't apply here, so referencing the visible title node is safe and preferred. */}
      <ZimmDrawerContent
        onClose={onClose}
        title={title}
        titleId={title ? titleId : undefined}
        titleStyle={titleStyle}
        labelledBy={labelledBy}
        ariaLabel={ariaLabel}
        contentStyles={styles.content}
        headerStyles={styles.header}
        headerTitleStyles={styles.headerTitle}
        closeButtonStyles={styles.closeButton}
      >
        {children}
      </ZimmDrawerContent>
    </Drawer>
  );
};

{
  "compilerOptions": {
    // Type-checking only — Babel handles transpilation.
    "noEmit": true,

    // Path aliases — keep in sync with babel.config.js, vitest.config.ts, .storybook/main.js
    // (jest.config.js has its own separate alias entries for @salesforce/pwa-kit-dev's
    // internal tooling — see .docs/architecture.md — not part of this sync group)
    "paths": {
      "~/*": ["./*"],
      "app/*": ["./overrides/app/*"]
    },
    "isolatedModules": true,

    // Language
    "target": "ES2019",
    "lib": ["ES2019", "DOM"],
    "jsx": "react-jsx",

    // Modules
    "module": "ESNext",
    "moduleResolution": "bundler",
    "esModuleInterop": true,

    // Strictness
    "strict": true,

    // Skip type-checking of vendored .d.ts files in node_modules.
    "skipLibCheck": true
  },
  "include": ["overrides/**/*", "vitest.config.ts", "vitest.setup.ts"]
}

